package com.servicerca.service; import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.*;import javax.crypto.spec.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.Base64;
@Service public class CryptoService{private final SecretKeySpec key;private final SecureRandom random=new SecureRandom();public CryptoService(@Value("${app.encryption-key}")String key){this.key=new SecretKeySpec(key.substring(0,32).getBytes(StandardCharsets.UTF_8),"AES");}public String encrypt(String value){try{byte[]iv=new byte[12];random.nextBytes(iv);var c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));return Base64.getEncoder().encodeToString(iv)+"."+Base64.getEncoder().encodeToString(c.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(GeneralSecurityException e){throw new IllegalStateException(e);}}}
